const READ_ERROR_KINDS_BY_STATUS: ReadonlyMap<number, ReadErrorKind> = new Map<number, ReadErrorKind>([
  [0, 'unreachable'],
  [401, 'unauthorised'],
  [403, 'forbidden'],
  [404, 'notFound'],
  [409, 'conflict'],
  [429, 'rateLimited'],
]);

/** The status from which a failure is the server's own. */
const SERVER_ERROR_STATUS = 500;

/** The kind of a read that failed with *status*. */
